def main() -> int:
    (OUT / "catalog.json").write_text(json.dumps(CATALOG, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    for cloud in ("azure", "aws", "gcp"):
        items = [x for x in CATALOG if x["cloud"] == cloud]
        (OUT / f"{cloud}.json").write_text(json.dumps(items, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    summary = {
        "sources": ["https://learn.microsoft.com/en-us/azure/?product=popular", "https://docs.aws.amazon.com/", "https://cloud.google.com/products"],
        "note": "Curated skills catalog derived from official product catalogs; console URLs for navigation. Not an exhaustive copy of all docs.",
        "counts": {c: sum(1 for x in CATALOG if x["cloud"] == c) for c in ("azure","aws","gcp")},
        "total": len(CATALOG),
    }
    (OUT / "summary.json").write_text(json.dumps(summary, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(summary, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
